import json
# Dump assistant text + tool_use one-liners to per-session text files (line-indexed) for grep
def txt(c):
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if b.get('type')=='text': out.append(b.get('text',''))
        return '\n'.join(out)
    return ''
for fn,out in [('c4987da0-9b92-4860-a389-7d95f1c5d56f.jsonl','/tmp/s1_assist.txt'),
               ('ecfde6a3-dcfa-46bd-8e47-d9800e334d03.jsonl','/tmp/s2_assist.txt')]:
    with open(out,'w') as f:
        idx=0
        for line in open(fn):
            try: d=json.loads(line)
            except: continue
            if d.get('type')=='assistant':
                t=txt(d.get('message',{}).get('content'))
                if t.strip():
                    f.write(f"\n===ASSIST#{idx}===\n{t}\n")
                    idx+=1
    import os
    print(out, os.path.getsize(out), "bytes")
EOF

