import json
from datetime import datetime
# Estimate session wall-clock from timestamps if present
for fn,tag in [('c4987da0-9b92-4860-a389-7d95f1c5d56f.jsonl','S1'),('ecfde6a3-dcfa-46bd-8e47-d9800e334d03.jsonl','S2')]:
    ts=[]
    # check for timestamp fields
    keys_seen=set()
    for line in open(fn):
        try: d=json.loads(line)
        except: continue
        for k in ('timestamp','ts','time','createdAt'):
            if k in d: ts.append(d[k]); keys_seen.add(k)
    print(tag, "timestamp keys:", keys_seen, "count:", len(ts))
    if ts:
        print("  first:",ts[0]," last:",ts[-1])
EOF
